  const x0 = s.kind === 'circle' ? s.cx - s.r : s.x0, x1 = s.kind === 'circle' ? s.cx + s.r : s.x1;
  const z0 = s.kind === 'circle' ? s.cz - s.r : s.z0, z1 = s.kind === 'circle' ? s.cz + s.r : s.z1;
